# Run from repository root: Rscript run_tests.R [optional Praat executable]
source("analyze_acoustics.R")
source("plot_f0_contours.R")
root <- normalizePath(getwd(),winslash="/")
tmp <- tempfile("acoustic_tests_");dir.create(tmp)
results <- list()
test <- function(name,code) {
  ans<-tryCatch({force(code);"PASS"},error=function(e)paste("FAIL",conditionMessage(e)))
  results[[name]] <<- data.frame(test=name,result=ans);cat(name,": ",ans,"\n",sep="")
}
assert <- function(ok,msg="Assertion failed")if(!isTRUE(ok))stop(msg)
expect_error <- function(expr,pattern=NULL) {
  e<-tryCatch({force(expr);NULL},error=identity)
  assert(inherits(e,"error"),"Expected an error")
  if(!is.null(pattern))assert(grepl(pattern,conditionMessage(e)),conditionMessage(e))
}
read_utf8 <- function(f)readLines(f,encoding="UTF-8",warn=FALSE)
d<-read_measurements("synthetic_measurements.csv")
write_case <- function(x,name) {p<-file.path(tmp,paste0(name,".csv"));write.csv(x,p,row.names=FALSE,na="");p}
qc_case <- function(x,name) {p<-write_case(x,name);qc_measurements(read_measurements(p),file.path(tmp,paste0("qc_",name)))}
test("normal_input_and_missing_f0",{assert(nrow(d)==256);assert(sum(is.na(d$f0_mean_st))==2);qc_measurements(d,file.path(tmp,"qc_good"))})
test("missing_column",expect_error(qc_case(d[setdiff(names(d),"block")],"missing_column"),"failed QC"))
test("duplicate_token",expect_error(qc_case(rbind(d,d[1,]),"duplicate"),"failed QC"))
test("duplicate_cell_new_id",{x<-rbind(d,d[1,]);x$token_id[nrow(x)]<-"different";expect_error(qc_case(x,"duplicate_cell"),"failed QC")})
test("negative_duration",{x<-d;x$syllable_duration_ms[1]<- -1;expect_error(qc_case(x,"negative"),"failed QC")})
test("nonnumeric",{x<-d;x$f0_onset_st[1]<-"bad";expect_error(qc_case(x,"nonnumeric"),"failed QC")})
test("infinite_value",{x<-d;x$f0_mean_st[1]<-Inf;expect_error(qc_case(x,"infinite"),"failed QC")})
test("missing_entire_condition",expect_error(qc_case(d[d$construction=="SN",],"SN_only"),"failed QC"))
test("unpaired_speaker",{x<-d[!(d$speaker=="S01"&d$construction=="NPC"),];expect_error(qc_case(x,"unpaired_speaker"),"failed QC")})
test("unpaired_item",{x<-d[!(d$item_pair=="01"&d$construction=="NPC"),];expect_error(qc_case(x,"unpaired_item"),"failed QC")})
test("undefined_f0",{x<-d;x$f0_onset_st[1]<-"--undefined--";p<-write_case(x,"undefined");assert(is.na(read_measurements(p)$f0_onset_st[1]))})
test("suspicious_value_retained",{x<-d;x$f0_mean_st[1]<-50;q<-qc_case(x,"suspect");assert(any(q$check=="unusual_f0_st"));assert(nrow(x)==nrow(d))})
test("all_missing_measure",{x<-d;x$f0_mean_st[]<-NA;expect_error(prepare_model_data(x,"f0_mean_st"),"Insufficient")})
test("alias_conflict",{x<-d;x$condition<-ifelse(x$construction=="SN","NPC","SN");expect_error(qc_case(x,"alias"),"failed QC")})
test("per_measure_missingness",{p<-prepare_model_data(d,"f0_mean_st");assert(nrow(p$data)==254);assert(nrow(prepare_model_data(d,"vowel_duration_ms")$data)==256)})
test("subset_unpaired_group",{x<-d;x$f0_mean_st[x$speaker=="S01"&x$construction=="NPC"]<-NA;expect_error(prepare_model_data(x,"f0_mean_st"),"without both")})
test("profile_failure_visible",{z<-profile_interval(NULL,function(...)stop("synthetic CI failure"));assert(z$status=="failed"&&is.na(z$lower))})
test("profile_warning_visible",{z<-profile_interval(NULL,function(...){warning("synthetic warning");matrix(c(-1,1),1)});assert(z$status=="warning")})
test("explicit_treatment_coding",{p<-prepare_model_data(d,"vowel_duration_ms");assert(identical(colnames(model.matrix(~construction,p$data)),c("(Intercept)","constructionNPC")))})
test("singular_model_retained_as_warning",{p<-prepare_model_data(d,"vowel_duration_ms");set.seed(5);p$data$vowel_duration_ms<-rnorm(nrow(p$data),100,2);f<-fit_candidate(p$data,"vowel_duration_ms","full");assert(f$log$status=="warning");assert(f$log$singular)})
test("no_implicit_random_simplification",expect_error(run_analysis("synthetic_measurements.csv",file.path(tmp,"reason"),random="intercepts",ci=FALSE),"requires"))
test("rate_centering",{p<-prepare_model_data(d,"syllable_duration_ms",TRUE)$data;assert(max(abs(tapply(p$rate_within,p$speaker,mean)))<1e-10)})
test("end_to_end_models_ci_block_log",{
  status<-run_analysis("synthetic_measurements.csv",file.path(tmp,"analysis"),include_block=TRUE,log_duration=TRUE,primary="vowel_duration_ms")
  assert(!any(status$status=="failed"),paste(status$detail[status$status=="failed"],collapse=";"))
  r<-read.csv(file.path(tmp,"analysis","construction_effects.csv"));assert(nrow(r)>=12)
  assert(any(r$ci_status=="success"));assert(any(grepl("_log_sensitivity",r$measure)))
  assert(file.exists(file.path(tmp,"analysis","vowel_duration_ms_diagnostics.pdf")))
  assert(file.exists(file.path(tmp,"analysis","vowel_duration_ms_full_model.rds")))
  assert(file.exists(file.path(tmp,"analysis","qc_issues.csv")))
})
test("stale_outputs_rejected",expect_error(run_analysis("synthetic_measurements.csv",file.path(tmp,"analysis")),"new or empty"))
test("contour_output_and_equal_weights",{
  r<-plot_contours("synthetic_measurements.csv",file.path(tmp,"contour"));assert(nrow(r)==20)
  assert(file.exists(file.path(tmp,"contour","f0_contours.png")))
  z<-d[d$construction=="SN",];wanted<-mean(tapply(z$F0_t15_ST,z$speaker,mean,na.rm=TRUE));assert(abs(r$mean_st[r$construction=="SN"&r$time_percent==15]-wanted)<1e-10)
})
test("all_missing_contour",{x<-d;x[grep("^F0_t",names(x))]<-NA;p<-write_case(x,"all_missing_contour");expect_error(plot_contours(p,file.path(tmp,"all_missing_plot")),"All F0")})
test("single_speaker_plot",{x<-d[d$speaker=="S01",];p<-write_case(x,"single");r<-plot_contours(p,file.path(tmp,"single_plot"));assert(all(is.na(r$se_between_speakers)))})
test("missing_contour_column",{x<-d[setdiff(names(d),"F0_t05_ST")];p<-write_case(x,"missing_contour");expect_error(plot_contours(p,file.path(tmp,"missing_contour_plot")),"Missing contour")})
test("folder_merge_duplicate_detection",{p<-file.path(tmp,"duplicate_folder");dir.create(p);file.copy("synthetic_measurements.csv",file.path(p,"S01_20%.csv"));file.copy("synthetic_measurements.csv",file.path(p,"S02_20%.csv"));expect_error(qc_measurements(read_measurements(p),file.path(tmp,"qc_folder")),"failed QC")})
test("bad_rate_arithmetic",{x<-d;x$expected_non_bu_syllable_count<-5;x$effective_non_bu_articulation_duration_s<-1;expect_error(qc_case(x,"bad_rate"),"failed QC")})
test("invalid_f0_range",{x<-d;x$f0_range_st[1]<- -1;expect_error(qc_case(x,"bad_range"),"failed QC")})
test("block_prefix_normalisation",{x<-d;x$block<-paste(x$speaker,x$block,sep="_");p<-write_case(x,"block_prefix");z<-read_measurements(p);assert(length(unique(z$block))==2)})
test("failed_model_logged",{p<-prepare_model_data(d,"vowel_duration_ms");p$data$vowel_duration_ms[]<-NA;f<-fit_candidate(p$data,"vowel_duration_ms","full");assert(f$log$status=="failed"&&nzchar(f$log$error))})
test("unequal_token_counts_equal_speaker_weights",{x<-d[!(d$speaker=="S01" & d$construction=="SN" & d$block=="B02" & d$item_pair!="01"),];x$F0_t15_ST[x$construction=="SN"]<-ifelse(x$speaker[x$construction=="SN"]=="S01",20,0);p<-write_case(x,"unequal_tokens");r<-plot_contours(p,file.path(tmp,"unequal_plot"));assert(abs(r$mean_st[r$construction=="SN"&r$time_percent==15]-2.5)<1e-10)})
# Optional Praat integration: real executable, synthetic files; no real data read.
a<-commandArgs(trailingOnly=TRUE)
if(length(a)) {
  praat<-normalizePath(a[1],winslash="/")
  call_praat <- function(script,args) {
    log<-tempfile(tmpdir=tmp);err<-paste0(log,".err")
    code<-system2(praat,c("--run","--FULL-TRUST",shQuote(file.path(root,script)),vapply(args,shQuote,character(1))),stdout=log,stderr=err,wait=TRUE,timeout=30)
    if(code!=0)stop("Praat exit ",code,"; inspect ",err)
  }
  fixture <- function(name) {p<-file.path(tmp,name);dir.create(p);call_praat("test_fixtures.praat",p);p}
  review <- function(p,actions,start=1,interval=1,save="yes")call_praat("check_textgrids.praat",c(p,".wav","1","yes","no","0.15",as.character(start),as.character(interval),save,actions))
  text <- function(p)paste(read_utf8(p),collapse="\n")
  test("praat_navigation_label_save_originals",{
    p<-fixture("navigation"); originals<-list.files(p,full.names=TRUE); before<-tools::md5sum(originals)
    review(p,"previous replay label next_file save_exit")
    assert(identical(before,tools::md5sum(originals)),"Original WAV/TextGrid modified")
    saved<-list.files(file.path(p,"reviewed"),"review[0-9]+[.]TextGrid$",full.names=TRUE)
    assert(length(saved)==2);t<-text(saved[1]);assert(grepl("synthetic_checked",t));assert(grepl('name = "other"',t));assert(grepl('name = "points"',t));assert(grepl("untouched",t))
    progress<-paste(vapply(list.files(file.path(p,"reviewed"),"progress",full.names=TRUE),text,character(1)),collapse="\n")
    assert(grepl("button=1",progress)&&grepl("button=2",progress)&&grepl("button=4",progress)&&grepl("button=5",progress))
  })
  test("praat_next_button",{p<-fixture("next_button");review(p,"next save_exit");f<-list.files(file.path(p,"reviewed"),"progress",full.names=TRUE);t<-paste(vapply(f,text,character(1)),collapse="\n");assert(grepl("button=3",t)&&grepl("button=5",t));assert(file.exists(file.path(p,"reviewed","test2.review1.TextGrid")))})
  test("praat_stale_popup_split",{p<-fixture("split");review(p,"split save_exit");f<-list.files(file.path(p,"reviewed"),"review[0-9]+[.]TextGrid$",full.names=TRUE)[1];t<-text(f);assert(!grepl("must_not_be_written",t));assert(grepl("intervals: size = 4",t))})
  test("praat_editor_label_preserved",{p<-fixture("editor");review(p,"editor_label save_exit");f<-list.files(file.path(p,"reviewed"),"review[0-9]+[.]TextGrid$",full.names=TRUE)[1];assert(grepl("editor_edit",text(f)))})
  test("praat_same_count_boundary_move_stale_label",{p<-fixture("move");review(p,"boundary_move");f<-list.files(file.path(p,"reviewed"),"review[0-9]+[.]TextGrid$",full.names=TRUE)[1];t<-text(f);assert(!grepl("must_not_be_written",t));assert(grepl("0.3",t))})
  test("praat_editor_popup_conflict",{p<-fixture("conflict");review(p,"editor_conflict");f<-list.files(file.path(p,"reviewed"),"review[0-9]+[.]TextGrid$",full.names=TRUE)[1];t<-text(f);assert(grepl("editor_edit",t));assert(!grepl("must_not_be_written",t))})
  test("praat_resume_and_exit_forces_save",{p<-fixture("resume");review(p,"save_exit",2,2,"no");assert(file.exists(file.path(p,"reviewed","test2.review1.TextGrid")))})
  test("praat_all_empty_intervals",{p<-fixture("empty");for(f in list.files(p,"TextGrid$",full.names=TRUE)){x<-read_utf8(f);x<-gsub('text = "bu"','text = ""',x,fixed=TRUE);writeLines(x,f,useBytes=TRUE)};review(p,"next");assert(length(list.files(file.path(p,"reviewed"),"review[0-9]+[.]TextGrid$"))==2)})
  test("praat_no_original_or_prior_output_overwrite",{p<-fixture("repeat");review(p,"label save_exit");f<-list.files(file.path(p,"reviewed"),full.names=TRUE);before<-tools::md5sum(f);review(p,"save_exit");assert(identical(before,tools::md5sum(f)));assert(file.exists(file.path(p,"reviewed","test1.review2.TextGrid")))})
} else results[["praat"]]<-data.frame(test="praat",result="NOT RUN: supply Praat executable; GUI interaction is always manual.")
r<-do.call(rbind,results)
write.csv(r,"TEST_RESULTS.csv",row.names=FALSE)
capture.output(sessionInfo(),file="TEST_SESSION.txt")
cat("Local test artifacts: ",tmp,"\n",sep="")
if(any(startsWith(r$result,"FAIL")))quit(status=1)
